<template><div class="page"><header class="page-head"><div><button class="back" @click="$router.push('/')">← New Analysis</button><h1>{{a?.name||'UX Analysis Report'}}</h1><p>Approach 2 · {{a?.perspectives?.length||0}} perspectives · {{a?.scenarios?.length||0}} scenarios</p></div><div class="actions"><button class="ghost-btn" @click="download">Download HTML</button><button class="primary" @click="openHtml">Open Report</button></div></header><section v-if="a && a.status!=='completed'" class="card progress-card"><div class="eyebrow">ANALYSIS PROGRESS</div><h2>{{a.status==='analyzing'?'Codex is analyzing your PRD…':a.status==='generating-wireframes'?'Generating scenario wireframes…':'Analysis failed'}}</h2><p>{{a.summary}}</p><div class="progress-track"><span :style="{width:a.status==='generating-wireframes'?'70%':a.status==='failed'?'100%':'35%'}"></span></div><small>Codex analysis → scenario planning → wireframe generation → final report</small></section><div v-if="a && a.status==='completed'" class="tabs"><button class="tab active">Overview</button><button v-for="p in a.perspectives" :key="p" class="tab">{{label(p)}}</button></div><section v-if="a" class="card hero"><div class="eyebrow">EXECUTIVE SUMMARY</div><h2>UX analysis with scenario-driven wireframes</h2><p>{{a.summary}}</p><div class="metrics"><div><b>{{a.perspectives.length}}</b><span>Perspectives</span></div><div><b>{{a.scenarios.length}}</b><span>User scenarios</span></div><div><b>{{totalScreens}}</b><span>Wireframe screens</span></div><div><b>{{a.openDecisions}}</b><span>Open decisions</span></div></div></section><section class="section-block"><div class="section-title"><div><h2>User Scenarios</h2><p>Review each journey and its wireframe stages.</p></div></div><div class="scenario-grid"><article v-for="s in a.scenarios" :key="s.id" class="scenario-card" @click="$router.push(`/analysis/${a.id}/scenario/${s.id}`)"><div class="scenario-icon">{{s.icon||'◇'}}</div><h3>{{s.title}}</h3><p>{{s.description}}</p><div class="card-foot"><span>{{s.stages?.length||0}} screens</span><span>→</span></div></article></div></section></div></template>
<script setup lang="ts">import {computed,ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import {api} from '../api';const route=useRoute();const a=ref<any>();onMounted(async()=>{a.value=await api.get(route.params.id as string);if(a.value.status!=='completed' && a.value.status!=='failed'){const timer=window.setInterval(async()=>{a.value=await api.get(route.params.id as string);if(a.value.status==='completed'||a.value.status==='failed')window.clearInterval(timer)},2000)}});const totalScreens=computed(()=>a.value?.scenarios?.reduce((n:number,s:any)=>n+(s.stages?.length||0),0)||0);function label(p:string){return p.split('-').map(x=>x[0].toUpperCase()+x.slice(1)).join(' ')}function download(){if(!a.value?.html)return;const b=new Blob([a.value.html],{type:'text/html'});const u=URL.createObjectURL(b);const x=document.createElement('a');x.href=u;x.download=`${a.value.name}.html`;x.click();URL.revokeObjectURL(u)}function openHtml(){if(!a.value?.html)return;const w=window.open();w?.document.write(a.value.html);w?.document.close()}</script>
